from __future__ import annotations

import math
from itertools import accumulate

from risk.types import Drawdown, Returns


def max_drawdown(returns: Returns) -> tuple[Drawdown, ...]:
    """The deepest fall below the running peak of wealth, with its dates, per ticker."""
    dates = (returns.base_date, *returns.dates)
    return tuple(_drawdown(ticker, dates, returns.values[ticker]) for ticker in returns.tickers)


def _drawdown(ticker: str, dates: tuple[str, ...], log_returns: tuple[float, ...]) -> Drawdown:
    """Wealth starts at 1 on the first date; the first deepest fall wins, from the first date of its peak."""
    log_wealth = (0.0, *accumulate(log_returns))
    peak = trough = best_peak = 0
    depth = 0.0
    for i, w in enumerate(log_wealth):
        if w > log_wealth[peak]:
            peak = i
        fall = math.expm1(w - log_wealth[peak])
        if fall < depth:
            depth, best_peak, trough = fall, peak, i
    return Drawdown(ticker=ticker, depth=depth, peak_date=dates[best_peak], trough_date=dates[trough])

